const item = $input.first();

const input = item.json || {};
const binary = item.binary || {};

const hasPdfFile =
  input.meta?.hasPdfFile === true ||
  Object.values(binary).some(file =>
    file.mimeType === 'application/pdf' ||
    file.fileExtension === 'pdf' ||
    file.fileName?.toLowerCase().endsWith('.pdf')
  );

const hasBinaryFile =
  input.meta?.hasBinaryFile === true ||
  Object.keys(binary).length > 0;

const hasCvText =
  input.meta?.hasCvText === true ||
  !!input.cvText;

const hasMessage =
  input.meta?.hasMessage === true ||
  !!input.userMessage;

const inputType = hasPdfFile
  ? 'file'
  : hasCvText
    ? 'cv_text'
    : 'message';

const requestType = hasPdfFile || hasCvText
  ? 'cv_upload'
  : 'text_message';

return [
  {
    json: {
      ...input,
      success: true,
      inputType,
      requestType,

      meta: {
        ...(input.meta || {}),
        source: inputType,
        hasBinaryFile,
        hasPdfFile,
        hasCvText,
        hasMessage,
        submittedCvNow: hasPdfFile || hasCvText,
        binaryKeys: input.meta?.binaryKeys || Object.keys(binary)
      }
    },
    binary
  }
];

const item = $input.first();

const json = item.json || {};
const body = json.body || json || {};
const query = json.query || body.query || {};
const params = json.params || body.params || {};
const binary = item.binary || {};

const readBinaryField = (key) => {
  const field = binary[key];
  if (!field) return null;

  return field.fileName ? String(field.fileName).trim() : null;
};

const safeJsonParse = (value, fallback = null) => {
  if (!value) return fallback;
  if (typeof value === 'object') return value;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
};

const hasBinaryFile = Object.keys(binary).length > 0;

const hasPdfFile = Object.values(binary).some(file =>
  file.mimeType === 'application/pdf' ||
  file.fileExtension === 'pdf' ||
  file.fileName?.toLowerCase().endsWith('.pdf')
);

const userId =
  body.userId ??
  body.user_id ??
  json.userId ??
  json.user_id ??
  query.userId ??
  query.user_id ??
  params.userId ??
  params.user_id ??
  readBinaryField('userId') ??
  null;

const chatId =
  body.chatId ??
  body.chat_id ??
  json.chatId ??
  json.chat_id ??
  query.chatId ??
  query.chat_id ??
  params.chatId ??
  params.chat_id ??
  readBinaryField('chatId') ??
  null;

const cvId =
  body.cvId ??
  body.cv_id ??
  body.cvData?.cv_id ??
  json.cvId ??
  json.cv_id ??
  json.cvData?.cv_id ??
  query.cvId ??
  query.cv_id ??
  params.cvId ??
  params.cv_id ??
  readBinaryField('cvId') ??
  null;

if (!userId) {
  throw new Error("userId is required");
}

if (!chatId) {
  throw new Error("chatId is required");
}

const userMessage =
  body.message ||
  body.userMessage ||
  body.messageText ||
  body.text ||
  json.message ||
  json.userMessage ||
  json.messageText ||
  json.text ||
  query.message ||
  '';

const cvData =
  body.cvData ||
  json.cvData ||
  null;

const cvAnalysis =
  safeJsonParse(cvData?.analysis_json) ||
  safeJsonParse(cvData?.cv_text) ||
  null;

const cvText =
  body.cvText ||
  body.cv_text ||
  body.extractedText ||
  body.fileText ||
  json.cvText ||
  json.cv_text ||
  cvData?.improved_cv ||
  cvAnalysis?.summary ||
  cvAnalysis?.analysis_json?.summary ||
  cvData?.cv_text ||
  '';

const chatHistory = Array.isArray(body.history)
  ? body.history.map(msg => ({
      role: msg.role,
      content: msg.message,
      type: msg.type,
      createdAt: msg.created_at
    }))
  : [];

const submittedCvNow = hasPdfFile || !!cvText;

const requestType = hasPdfFile ? 'cv_upload' : 'text_message';

return [
  {
    json: {
      success: true,
      requestType,
      chatId,
      userId,
      cvId,
      userMessage,
      cvText,
      cvData,
      cvAnalysis,
      chatHistory,
      meta: {
        source: hasPdfFile ? 'file' : (submittedCvNow ? 'cv_text' : 'message'),
        hasFile: hasPdfFile,
        hasBinaryFile,
        hasPdfFile,
        binaryKeys: Object.keys(binary),
        hasCvText: !!cvText,
        hasMessage: !!userMessage,
        submittedCvNow,
        isFromUser: !!userId,
        hasCvData: !!cvData,
        hasCvAnalysis: !!cvAnalysis,
        hasHistory: chatHistory.length > 0,
        historyCount: chatHistory.length
      }
    },
    binary
  }
];

const input = $('Normalize Input').first().json;

// =========================
// Helpers
// =========================
const safeParse = (value, fallback = null) => {
  try {
    if (value === undefined || value === null || value === '') return fallback;
    return typeof value === 'string' ? JSON.parse(value) : value;
  } catch {
    return fallback;
  }
};

const isPlainObject = (value) => {
  return value && typeof value === 'object' && !Array.isArray(value);
};

const hasObjectData = (obj) => {
  return isPlainObject(obj) && Object.keys(obj).length > 0;
};

const cleanValue = (value) => {
  if (value === undefined || value === null) return undefined;

  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? undefined : trimmed;
  }

  if (Array.isArray(value)) {
    const cleanedArray = value
      .map(cleanValue)
      .filter(v => v !== undefined);

    return cleanedArray.length > 0 ? cleanedArray : undefined;
  }

  if (isPlainObject(value)) {
    const cleanedObject = {};

    for (const [key, val] of Object.entries(value)) {
      const cleaned = cleanValue(val);
      if (cleaned !== undefined) {
        cleanedObject[key] = cleaned;
      }
    }

    return Object.keys(cleanedObject).length > 0 ? cleanedObject : undefined;
  }

  return value;
};

const pick = (obj, keys) => {
  const result = {};

  keys.forEach(key => {
    if (obj && obj[key] !== undefined && obj[key] !== null && obj[key] !== '') {
      result[key] = obj[key];
    }
  });

  return result;
};

const detectTargetRole = (message = '') => {
  const text = String(message).toLowerCase();

  if (
    text.includes('front end') ||
    text.includes('frontend') ||
    text.includes('front-end') ||
    text.includes('فرونت') ||
    text.includes('واجهة أمامية') ||
    text.includes('واجهه اماميه')
  ) {
    return 'Front-End Developer';
  }

  if (
    text.includes('back end') ||
    text.includes('backend') ||
    text.includes('back-end') ||
    text.includes('باك') ||
    text.includes('خلفية') ||
    text.includes('خلفيه')
  ) {
    return 'Back-End Developer';
  }

  if (
    text.includes('full stack') ||
    text.includes('fullstack') ||
    text.includes('فل ستاك') ||
    text.includes('فول ستاك')
  ) {
    return 'Full-Stack Developer';
  }

  if (
    text.includes('ai') ||
    text.includes('ذكاء اصطناعي') ||
    text.includes('automation') ||
    text.includes('اوتوميشن')
  ) {
    return 'AI Automation Developer';
  }

  return '';
};

// =========================
// Source data
// =========================
const cvData = input.cvData || {};
const parsedAnalysis = safeParse(cvData.analysis_json, {});
const cvAnalysis = hasObjectData(input.cvAnalysis) ? input.cvAnalysis : parsedAnalysis;

const improvedCv = safeParse(cvData.improved_cv, null);

const userMessage = input.userMessage || '';

const cvId =
  input.cvId ||
  cvData.cv_id ||
  cvAnalysis.cvId ||
  null;

const cvText = String(
  input.cvText ||
  cvData.cv_text ||
  ''
);

const fileName =
  cvData.file_name ||
  cvAnalysis.fileName ||
  null;

const targetRole =
  input.targetRole ||
  cvData.target_role ||
  cvAnalysis.targetRole ||
  detectTargetRole(userMessage);

const hasCv = Boolean(
  cvId ||
  cvText.trim().length > 0 ||
  fileName ||
  hasObjectData(cvAnalysis)
);

// =========================
// Clean CV context
// =========================
const cvContext = cleanValue({
  id: cvId,
  fileName,
  textPreview: cvText.slice(0, 2500),
  candidateName: cvAnalysis.candidateName,
  currentRole: cvAnalysis.currentRole,
  totalYearsExperience: cvAnalysis.totalYearsExperience,
  technicalSkills: cvAnalysis.technicalSkills,
  softSkills: cvAnalysis.softSkills,
  education: cvAnalysis.education,
  experience: cvAnalysis.experience,
  projects: cvAnalysis.projects
});

// =========================
// Clean analysis context
// =========================
const analysisContext = cleanValue({
  atsScore: cvData.ats_score ?? cvAnalysis.atsScore,
  overallScore: cvAnalysis.overallScore,
  status: cvData.status || cvAnalysis.status,
  atsLevel: cvAnalysis.atsLevel,
  scoreBreakdown: cvAnalysis.scoreBreakdown,
  strengths: cvAnalysis.strengths,
  weaknesses: cvAnalysis.weaknesses,
  missingKeywords: cvAnalysis.missingKeywords,
  matchedKeywords: cvAnalysis.matchedKeywords,
  missingJobRequirements: cvAnalysis.missingJobRequirements,
  recommendations: cvAnalysis.recommendations,
  summary: cvAnalysis.summary,
  matchSummary: cvAnalysis.matchSummary
});

// =========================
// Improved CV context, only if exists
// =========================
const improvedCvContext = cleanValue(improvedCv);

// =========================
// Chat history
// =========================
const historyRows = Array.isArray(input.chatHistory)
  ? input.chatHistory
  : [];

const uniqueMessages = [];
const seen = new Set();

historyRows
  .slice(-8)
  .forEach(m => {
    const role = m.role || '';
    const type = m.type || '';
    const message = m.message || m.content || '';
    const key = `${role}:${type}:${message}`;

    if (!seen.has(key)) {
      seen.add(key);
      uniqueMessages.push(m);
    }
  });

const chatHistory = cleanValue(
  uniqueMessages
    .filter(m => m.message || m.content || m.data_json)
    .map(m => ({
      role: m.role === 'bot' ? 'assistant' : m.role,
      type: m.type || null,
      message: m.message || m.content || '',
      data: safeParse(m.data_json, null),
      createdAt: m.createdAt || m.created_at || null
    }))
);

// =========================
// Build final AI context
// =========================
const aiContext = cleanValue({
  success: true,
  requestType: 'text_message',

  userId: input.userId,
  chatId: input.chatId,
  userMessage,

  hasCv,
  targetRole,

  cv: cvContext,
  analysis: analysisContext,
  improvedCv: improvedCvContext,
  chatHistory,

  instructions: {
    answerInArabic: true,
    useAnalysisFirst: true,
    useCvTextForDetails: true,
    useAnalysisForInsights: true,
    doNotReanalyzeUnlessAsked: true,
    doNotInventMissingExperience: true,
    providePracticalSuggestions: true,
    keepResponseFocusedOnUserQuestion: true
  }
});

// =========================
// Output
// =========================
return [
  {
    json: aiContext || {
      success: true,
      requestType: 'text_message',
      userMessage,
      hasCv: false,
      instructions: {
        answerInArabic: true
      }
    }
  }
];

