const input = $('Prepare CV Payload1').first().json;
const aiOutput = $input.first().json;

// =========================
// Helpers
// =========================
const safeParse = (value, fallback = null) => {
  try {
    if (value === undefined || value === null || value === '') return fallback;

    if (typeof value === 'string') {
      let raw = value.trim();

      // Remove code block if AI accidentally returned ```json ... ```
      raw = raw
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();

      return JSON.parse(raw);
    }

    return value;
  } catch {
    return fallback;
  }
};

const isPlainObject = (value) => {
  return value && typeof value === 'object' && !Array.isArray(value);
};

const toArray = (value) => {
  return Array.isArray(value) ? value : [];
};

const toObject = (value, fallback = {}) => {
  return isPlainObject(value) ? value : fallback;
};

const toNumberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
};

const cleanValue = (value) => {
  if (value === undefined || value === null) return undefined;

  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? undefined : trimmed;
  }

  if (Array.isArray(value)) {
    const arr = value
      .map(cleanValue)
      .filter(v => v !== undefined);

    return arr.length ? arr : undefined;
  }

  if (isPlainObject(value)) {
    const obj = {};

    for (const [key, val] of Object.entries(value)) {
      const cleaned = cleanValue(val);
      if (cleaned !== undefined) {
        obj[key] = cleaned;
      }
    }

    return Object.keys(obj).length ? obj : undefined;
  }

  return value;
};

// =========================
// Extract AI response
// =========================
let raw =
  aiOutput.output ||
  aiOutput.text ||
  aiOutput.response ||
  aiOutput.message ||
  aiOutput.content ||
  aiOutput.json ||
  '';

let parsed = safeParse(raw, null);

if (!isPlainObject(parsed)) {
  parsed = {
    type: 'answer',
    answer: String(raw || ''),
    sections: {},
    suggestions: [],
    confidence: 0.5
  };
}

// =========================
// Normalize parsed response
// =========================
const allowedTypes = ['answer', 'improve', 'rewrite', 'explain_analysis'];

const type = allowedTypes.includes(parsed.type)
  ? parsed.type
  : 'answer';

const sections = toObject(parsed.sections, {});

const suggestions = toArray(parsed.suggestions);

const confidence = toNumberOrNull(parsed.confidence);

// =========================
// Read context safely
// =========================
const cvId =
  input.cv?.id ||
  input.cvId ||
  null;

const analysis = toObject(input.analysis, {});

const atsScore =
  analysis.atsScore ??
  analysis.overallScore ??
  null;

const status =
  analysis.status ||
  analysis.atsLevel ||
  null;

// =========================
// Build data_json cleanly
// =========================
const dataJson = cleanValue({
  type,
  answer: parsed.answer || '',
  sections,
  suggestions,
  confidence,
  basedOn: {
    cvId,
    atsScore,
    status,
    targetRole: input.targetRole || null
  }
}) || {
  type,
  answer: parsed.answer || '',
  sections: {},
  suggestions: [],
  confidence
};

// =========================
// Output
// =========================
return [
  {
    json: {
      success: true,

      userId: input.userId,
      chatId: input.chatId,
      cvId,

      role: 'assistant',
      type,

      answer: parsed.answer || '',

      summary: sections.summary || null,
      skills: toArray(sections.skills),
      experience: toArray(sections.experience),
      projects: toArray(sections.projects),

      sections,
      suggestions,
      confidence,

      data_json: dataJson
    }
  }
];

const item = $input.first();

const json = item.json || {};
const binary = item.binary || {};

const binaryKeys = Object.keys(binary);
const binaryKey = binaryKeys[0] || null;
const file = binaryKey ? binary[binaryKey] : null;

const userIdRaw = json.userId || json.user_id || null;
const chatIdRaw = json.chatId || json.chat_id || userIdRaw || null;

const userId = userIdRaw !== null ? Number(userIdRaw) : null;
const chatId = chatIdRaw !== null ? Number(chatIdRaw) : userId;

if (!file) {
  return [{
    json: {
      ...json,
      userId,
      chatId,
      inputType: 'file',
      requestType: 'cv_upload',
      isValid: false,
      error: 'No file uploaded',
      file: {
        binaryKey: null,
        fileId: null,
        fileName: null,
        mimeType: null,
        fileExtension: null,
        fileType: null
      },
      meta: {
        ...(json.meta || {}),
        source: 'file',
        hasBinaryFile: false,
        hasPdfFile: false,
        binaryKeys
      }
    }
  }];
}

const fileName = file.fileName || 'uploaded_cv.pdf';
const mimeType = file.mimeType || '';
const fileExtension = file.fileExtension || '';
const lowerName = fileName.toLowerCase();

const isPdf =
  mimeType === 'application/pdf' ||
  fileExtension.toLowerCase() === 'pdf' ||
  lowerName.endsWith('.pdf');

const fileId =
  json.fileId ||
  json.file_id ||
  json.file?.fileId ||
  file.id ||
  file.fileId ||
  `${chatId || 'user'}_${Date.now()}_${fileName}`;

return [{
  json: {
    ...json,
    userId,
    chatId,

    inputType: 'file',
    requestType: 'cv_upload',
    isValid: isPdf,
    error: isPdf ? null : 'Unsupported file type. Please upload PDF only.',

    file: {
      ...(json.file || {}),
      fileId,
      binaryKey,
      fileName,
      mimeType,
      fileExtension,
      fileType: isPdf ? 'pdf' : 'unsupported'
    },

    meta: {
      ...(json.meta || {}),
      source: 'file',
      hasBinaryFile: true,
      hasPdfFile: isPdf,
      binaryKeys
    }
  },
  binary
}];

const normalize = $('Normalize Input').first().json;
const cv = $('Generate CV Hash').first().json;

// =========================
// IDs from Normalize
// =========================
const userId = normalize.userId ? Number(normalize.userId) : null;
const chatId = normalize.chatId ? Number(normalize.chatId) : null;

const rawCvId =
  normalize.cvId ??
  normalize.cv_id ??
  null;

const cvId = rawCvId ? Number(rawCvId) : null;

// =========================
// CV Data from Generate CV Hash
// =========================
const fullCvText = cv.fullCvText || cv.cvText || '';
const cvText = cv.cvText || fullCvText || '';

// =========================
// Validation
// =========================
if (!userId || Number.isNaN(userId)) {
  throw new Error('Missing or invalid userId');
}

if (!chatId || Number.isNaN(chatId)) {
  throw new Error('Missing or invalid chatId');
}

if (!fullCvText || fullCvText.trim().length < 100) {
  throw new Error('CV text is missing or too short');
}

if (!cv.cvHash) {
  throw new Error('Missing cvHash');
}

if (!cvId || Number.isNaN(cvId)) {
  console.log('⚠️ cvId not found or invalid from backend');
}

// =========================
// Output
// =========================
return [
  {
    json: {
      success: true,
      requestType: 'cv_upload',
      inputType: 'file',

      userId,
      chatId,
      cvId: cvId && !Number.isNaN(cvId) ? cvId : null,

      file: {
        ...(cv.file || {}),
        fileId: cv.file?.fileId || null,
        fileName: cv.file?.fileName || 'uploaded_cv.pdf',
        mimeType: cv.file?.mimeType || 'application/pdf',
        fileType: cv.file?.fileType || 'pdf'
      },

      fileName: cv.file?.fileName || 'uploaded_cv.pdf',

      cvText,
      fullCvText,
      cvHash: cv.cvHash,

      stats: cv.stats || {
        charCount: fullCvText.length,
        wordCount: fullCvText.split(/\s+/).filter(Boolean).length
      }
    }
  }
];

const input = $input.first().json;

// نحاول نجيب cvId من كل مكان
let cvId =
  input.cvId ??
  input.cv_id ??
  input.query?.cvId ??
  input.body?.cvId ??
  null;

// نحول إلى رقم لو كان string
if (cvId !== null) {
  cvId = Number(cvId);

  if (isNaN(cvId)) {
    console.log('⚠️ cvId is not a valid number');
    cvId = null;
  }
}

// لا نكسر الفلو 🔥
if (!cvId) {
  console.log('⚠️ cvId not found, continuing...');
}

return [
  {
    json: {
      ...input,
      cvId
    }
  }
];

