// Clean extracted CV text
const item = $input.first();
const extracted = item.json || {};

const meta = $('Validate Uploaded File').first().json;

let rawText =
  extracted.text ||
  extracted.data ||
  extracted.cvText ||
  extracted.extractedText ||
  '';

if (!rawText || rawText.trim().length < 100) {
  throw new Error('Could not extract text from CV. File may be scanned or corrupted.');
}

let cleaned = rawText
  .replace(/\\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/[\u00A0\u200B\u200C\u200D\uFEFF]/g, ' ')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const maxLength = 3500;

const aiCvText =
  cleaned.length > maxLength
    ? cleaned.slice(0, 2500) + '\n...\n' + cleaned.slice(-1000)
    : cleaned;

return [
  {
    json: {
      success: true,
      requestType: 'cv_upload',
      inputType: 'file',

      userId: meta.userId,
      chatId: meta.chatId,

      file: meta.file,

      cvText: aiCvText,
      fullCvText: cleaned,

      stats: {
        charCount: cleaned.length,
        wordCount: cleaned.split(/\s+/).filter(Boolean).length
      }
    }
  }
];

