const meta = $('Validate Uploaded File').first().json;
const current = $input.first().json;

const sourceText = current.fullCvText || current.cvText || '';

if (!sourceText || !String(sourceText).trim()) {
  throw new Error('No CV text found to generate hash');
}

const normalizedText = String(sourceText)
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

// DJB2 Hash (سريع ومناسب)
let hash = 5381;

for (let i = 0; i < normalizedText.length; i++) {
  hash = ((hash << 5) + hash) + normalizedText.charCodeAt(i);
  hash = hash & hash;
}

const cvHash = String(Math.abs(hash));

return [
  {
    json: {
      ...meta,
      ...current,

      cvHash,
      textLength: normalizedText.length,

      file: {
        ...(meta.file || {}),
        ...(current.file || {}),
        fileId: current.file?.fileId || meta.file?.fileId || null,
        fileName: current.file?.fileName || meta.file?.fileName || null
      }
    }
  }
];

const input = $('Set CV Context').first().json;
const ai = $input.first().json;

// =========================
// Extract AI response
// =========================
let raw =
  ai.output ||
  ai.text ||
  ai.response ||
  ai.message ||
  ai.content ||
  '';

let parsed;

try {
  if (typeof raw === 'string') {
    raw = raw.trim();

    // Remove code block if AI accidentally returned ```json ... ```
    raw = raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```$/i, '')
      .trim();

    parsed = JSON.parse(raw);
  } else {
    parsed = raw;
  }
} catch (error) {
  throw new Error('AI returned invalid JSON: ' + error.message);
}

// =========================
// Safe helpers
// =========================
const toNumberOrNull = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
};

const toNumber = (value, fallback = 0) => {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
};

const toArray = (value) => {
  return Array.isArray(value) ? value : [];
};

const toObject = (value, fallback = {}) => {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : fallback;
};

const clampScore = (value) => {
  const score = Math.round(toNumber(value, 0));
  return Math.max(0, Math.min(100, score));
};

const getLevel = (score) => {
  if (score >= 90) return 'Excellent';
  if (score >= 75) return 'Very Good';
  if (score >= 60) return 'Good';
  if (score >= 45) return 'Fair';
  return 'Poor';
};

// =========================
// Convert IDs to numbers
// =========================
const userId = toNumberOrNull(input.userId);
const chatId = toNumberOrNull(input.chatId);
const cvId = toNumberOrNull(input.cvId || parsed.cvId);

// =========================
// Scores
// =========================
const atsScore = clampScore(parsed.atsScore);
const jobMatchScore = clampScore(parsed.jobMatchScore);
const overallScore = clampScore(parsed.overallScore ?? atsScore);

// Always calculate level from overallScore
const atsLevel = getLevel(overallScore);
const status = atsLevel;

// =========================
// Output
// =========================
return [
  {
    json: {
      success: true,

      userId,
      chatId,
      cvId,

      fileId: parsed.fileId || input.fileId || '',
      fileName: parsed.fileName || input.fileName || '',

      targetRole: parsed.targetRole || input.targetRole || '',
      jobDescriptionProvided: Boolean(parsed.jobDescriptionProvided),

      atsScore,
      jobMatchScore,
      overallScore,

      atsLevel,
      status,

      summary: parsed.summary || '',
      matchSummary: parsed.matchSummary || '',

      strengths: toArray(parsed.strengths),
      weaknesses: toArray(parsed.weaknesses),
      recommendations: toArray(parsed.recommendations),

      matchedKeywords: toArray(parsed.matchedKeywords),
      missingKeywords: toArray(parsed.missingKeywords),
      missingJobRequirements: toArray(parsed.missingJobRequirements),

      technicalSkills: toArray(parsed.technicalSkills),
      softSkills: toArray(parsed.softSkills),
      education: toArray(parsed.education),
      experience: toArray(parsed.experience),
      projects: toArray(parsed.projects),

      scoreBreakdown: toObject(parsed.scoreBreakdown, {
        formattingAndStructure: 0,
        keywordOptimization: 0,
        contentQuality: 0,
        atsCompatibility: 0
      }),

      isAnalyzed: true,

      analysis_json: {
        ...parsed,
        atsScore,
        jobMatchScore,
        overallScore,
        atsLevel,
        status
      }
    }
  }
];
